import time
from itertools import combinations

def _diffs(row):
    s=set()
    for i in range(len(row)):
        for j in range(i+1,len(row)):
            s.add(row[j]-row[i])
    return s

def _valid(rows):
    seen=set()
    for r in rows:
        for d in _diffs(r):
            if d in seen: return False
            seen.add(d)
    return True

def _scope(rows): return max(max(r) for r in rows)

def _greedy(max_scope, used):
    row=[0]; cm=0
    while len(row)<7:
        found=False
        for v in range(cm+1, max_scope+1):
            ok=True
            for x in row:
                if (v-x) in used: ok=False; break
            if ok:
                row.append(v)
                for x in row[:-1]: used.add(v-x)
                cm=v; found=True; break
        if not found: return None
    return row

t=time.time()
for ms in [105,108,112,120]:
    used=set(); rows=[]; ok=True
    for _ in range(7):
        r=_greedy(ms, used)
        if r is None: ok=False; break
        rows.append(r); used|= _diffs(r)
    if ok and rows:
        print(ms, 'valid' if _valid(rows) else 'INVALID', 'scope', _scope(rows))
print('elapsed', time.time()-t)
